    42→type NewLine struct {
    43→	Pos Pos
    44→}
    45→
    46→func (n *NewLine) Info() (Pos, string, string) {
    47→	return n.Pos, tok2str[tokNewLine], ""
    48→}
    49→
    50→type Comment struct {
    51→	Pos  Pos
